package com.queueless.controller;
import com.queueless.dao.UserDAO; import com.queueless.util.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*;
@WebServlet("/api/login") public class LoginServlet extends HttpServlet{
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{res.setContentType("application/json;charset=UTF-8");String email=req.getParameter("email"),pass=req.getParameter("password");if(email==null||pass==null||email.isBlank()||pass.isBlank()){res.setStatus(400);res.getWriter().write(JsonUtil.error("Email and password are required."));return;}try(Connection c=DBConnection.getConnection()){ResultSet r=new UserDAO().findForLogin(c,email.trim().toLowerCase());if(!r.next()||!PasswordUtil.matches(pass,r.getString("password"))){res.setStatus(401);res.getWriter().write(JsonUtil.error("Invalid email or password."));return;}HttpSession s=req.getSession(true);s.setAttribute("userId",r.getLong("id"));s.setAttribute("name",r.getString("name"));s.setAttribute("role",r.getString("role"));res.getWriter().write("{\"success\":true,\"name\":\""+JsonUtil.esc(r.getString("name"))+"\",\"role\":\""+r.getString("role")+"\"}");}catch(Exception e){res.setStatus(500);res.getWriter().write(JsonUtil.error("Unable to sign in right now."));}}
}
